$money=static function($value):string{
    if($value===null)return 'Unavailable';
    [$whole,$fraction]=explode('.',synk_management_money_text(synk_management_money_cents((string)$value)));
    return '₱'.preg_replace('/\B(?=(\d{3})+(?!\d))/u',',',$whole).'.'.$fraction;
};
$needsEvent=in_array($type,['event_attendance','absence_fines'],true);
?>
