  <div class="management-panel-heading"><div><p class="card-section-title mb-1">REPORT BUILDER</p><h2 id="report-controls-title">Choose, generate, and print</h2><p>Choose a report and period below. Generate a preview, then print or save it as PDF.</p></div></div>
  <form method="get" id="management-report-form" class="management-report-form">
    <div class="management-report-filters">
