      <div><label for="report-term">Term</label><select class="form-select" id="report-term" name="exam_term"><?php foreach(synk_management_exam_term_options()as$key=>$label): ?><option value="<?= $key ?>"<?= $key===$term['exam_term']?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div>
      <?php if($needsEvent): ?><div class="management-report-event"><label for="report-event">Event<?= $type==='event_attendance'?' (required)':'' ?></label><select class="form-select" id="report-event" name="event_id"><option value=""><?= $type==='event_attendance'?'Choose an event':'All events in this period' ?></option><?php foreach($report['events']as$event): ?><option value="<?= (int)$event['event_id'] ?>"<?= (int)$event['event_id']===$report['event_id']?' selected':'' ?>><?= synk_management_h($event['title'].' · '.$event['event_date'].' · '.ucfirst(strtolower($event['attendance_status'] ?? 'Not started'))) ?></option><?php endforeach; ?></select><?php if(!$report['events']): ?><small>No events in the selected period.</small><?php endif; ?></div><?php endif; ?>
    </div>
    <p class="management-report-description"><?= synk_management_h($report['types'][$type]['description']) ?></p>
    <details class="management-report-header-options"><summary>Print header and signatories</summary><div class="management-report-header-fields"><?php foreach(['institution'=>'Institution / school name','prepared_by'=>'Prepared by','checked_by'=>'Checked by','approved_by'=>'Approved by']as$key=>$label): ?><div><label for="report-<?= $key ?>"><?= $label ?></label><input class="form-control" id="report-<?= $key ?>" name="<?= $key ?>" maxlength="150" value="<?= synk_management_h($header[$key]) ?>"></div><?php endforeach; ?></div></details>
    <div class="management-report-actions"><button class="btn btn-primary" type="submit" name="generate" value="1" id="management-report-generate"><i class="bx bx-file me-1" aria-hidden="true"></i>Generate report</button><button class="btn btn-outline-primary" type="button" id="management-report-print"<?= !$report['generated']?' disabled':'' ?>><i class="bx bx-printer me-1" aria-hidden="true"></i>Print / Save as PDF</button><span id="management-report-stale" role="status" hidden>Options changed. Generate a new preview before printing.</span></div>
    <?php if($report['error']): ?><div class="alert alert-warning mt-3 mb-0" role="alert"><?= synk_management_h($report['error']) ?></div><?php endif; ?>
  </form>
</section>
<?php if(!$report['generated']): ?>
<section class="card management-panel management-report-start"><i class="bx bx-file-find" aria-hidden="true"></i><h2>Ready when you are</h2><p>Your report preview will appear here with a print header, period, totals, and sign-off lines.</p><p class="small">Collections are separated into contributions, event absence fines, and violation fines. Only posted payments appear as collections; unapplied violation catalog rates are excluded.</p></section>
