  <div class="management-report-metadata"><span>Generated <?= synk_management_h($report['generated_at']) ?> (Philippine time)</span><span>Generated by <?= synk_management_h($accountName) ?></span></div>
  <?php if(in_array($type,['collection_summary','collection_register'],true)): ?>
    <div class="management-report-metrics"><div><span>Total collected</span><strong><?= $money($data['totals']['collected']) ?></strong></div><div><span>Receipts</span><strong><?= number_format($data['totals']['receipts']) ?></strong></div><div><span>Students who paid</span><strong><?= number_format($data['totals']['students']) ?></strong></div></div>
    <?php if(!$data['totals']['reconciled']): ?><p class="management-report-caution"><strong>Reconciliation required.</strong> Receipt totals differ from saved allocations (<?= $money($data['totals']['allocated']) ?>). Review the ledger before using this report as a finalized financial statement.</p><?php endif; ?>
    <?php if($type==='collection_summary'): ?>
      <div class="management-report-table-scroll"><table class="management-report-table"><thead><tr><th scope="col">Payment category</th><th scope="col" class="amount">Receipts</th><th scope="col" class="amount">Students</th><th scope="col" class="amount">Amount collected</th></tr></thead><tbody><?php foreach($data['categories']as$key=>$category): ?><tr><td><?= synk_management_h($category['label']) ?><?php if($key==='violations'): ?><small><?= $category['collected']===null?'Student violation recording has not been prepared.':'Applied student violations only; catalog rates are excluded.' ?></small><?php endif; ?></td><td class="amount"><?= $category['receipts']===null?'-':number_format($category['receipts']) ?></td><td class="amount"><?= $category['students']===null?'-':number_format($category['students']) ?></td><td class="amount"><?= $money($category['collected']) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th scope="row">Total receipts received</th><td class="amount"><?= number_format($data['totals']['receipts']) ?></td><td class="amount"><?= number_format($data['totals']['students']) ?></td><td class="amount"><?= $money($data['totals']['collected']) ?></td></tr></tfoot></table></div>
      <p class="management-report-note">Category receipt and student counts may overlap when one receipt covers multiple categories. Overall counts are unique. Amounts use saved receipt allocations; they represent collections, not assessed charges.</p>
    <?php else: $number=0;foreach($data['categories']as$key=>$category): ?>
      <section class="management-report-category" data-report-category="<?= synk_management_h($key) ?>"><h3><?= synk_management_h($category['label']) ?><span><?= $money($category['collected']) ?></span></h3>
      <?php if($key==='violations' && $category['collected']===null): ?><p class="management-report-note">Unavailable: student violation recording has not been prepared. Violation catalog rates are not collections.</p><?php else: $categoryRows=array_filter($data['rows'],static function($row)use($key){return $row['category']===$key;}); ?>
      <div class="management-report-table-scroll"><table class="management-report-table"><thead><tr><th scope="col" class="report-number">No.</th><th scope="col">Receipt / recorded</th><th scope="col">Student</th><th scope="col">Payment for</th><th scope="col">Recorded by</th><th scope="col" class="amount">Amount</th></tr></thead><tbody><?php foreach($categoryRows as$row): ?><tr><td><?= ++$number ?></td><td><?= synk_management_h($row['receipt_number']) ?><small><?= synk_management_h($row['recorded_at']) ?></small></td><td><?= synk_management_h($row['student_name']) ?><small><?= synk_management_h($row['student_number']) ?></small></td><td><?= synk_management_h($row['title']) ?></td><td><?= synk_management_h($row['recorded_by_name']) ?></td><td class="amount"><?= $money($row['amount']) ?></td></tr><?php endforeach; ?><?php if(!$categoryRows): ?><tr><td colspan="6" class="report-empty">No payments recorded in this category for the selected period.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></section>
    <?php endforeach; ?><p class="management-report-note">Each numbered row is one receipt allocation. A receipt split across charges appears on multiple rows; the total includes each allocation once. Contributions linked to an event remain contributions.</p><?php endif; ?>
    <p class="management-report-note">Violation collections include only payments allocated to violations applied to individual students. No collections are inferred from catalog rates.</p>
  <?php elseif($type==='event_attendance'): ?>
    <div class="management-report-event-heading"><h3><?= synk_management_h($data['event']['title']) ?></h3><span>Event date: <?= synk_management_h($data['event']['event_date']) ?></span><strong class="management-report-status"><?= $data['finalized']?'FINALIZED ATTENDANCE':'PROVISIONAL · '.str_replace('_',' ',synk_management_h($data['status'])) ?></strong></div>
    <div class="management-report-metrics"><div><span>Roster students</span><strong><?= number_format($data['total']) ?></strong></div><div><span><?= $data['finalized']?'Absent':'Not yet recorded' ?></span><strong><?= number_format(count($data['groups']['absent'])) ?></strong></div><div><span>Present</span><strong><?= number_format(count($data['groups']['present'])) ?></strong></div></div>
    <?php if(!$data['finalized']): ?><p class="management-report-caution"><?= $data['status']==='NOT_STARTED'?'Attendance has not started. There is no frozen roster to report yet.':'Attendance is still open. Students without a scan are not yet recorded; they are not finalized absences and no absence fines are assessed by this report.' ?></p><?php endif; ?>
    <?php foreach(['absent'=>$data['finalized']?'Absent':'Not yet recorded','present'=>'Present']as$key=>$label): ?>
      <section class="management-report-category" data-report-category="<?= $key ?>"><h3><?= $label ?><span><?= count($data['groups'][$key]) ?> students</span></h3><div class="management-report-table-scroll"><table class="management-report-table"><thead><tr><th scope="col" class="report-number">No.</th><th scope="col">Student ID</th><th scope="col">Student name</th><th scope="col">Attendance recorded</th></tr></thead><tbody><?php foreach($data['groups'][$key]as$row): ?><tr data-attendance-number="<?= $row['number'] ?>"><td><?= $row['number'] ?></td><td><?= synk_management_h($row['student_number']) ?></td><td><?= synk_management_h($row['student_name']) ?></td><td><?= synk_management_h($row['recorded_at'] ?? '-') ?></td></tr><?php endforeach; ?><?php if(!$data['groups'][$key]): ?><tr><td colspan="4" class="report-empty">No students in this category.</td></tr><?php endif; ?></tbody></table></div></section>
    <?php endforeach; ?><p class="management-report-note">Based on this event's saved attendance roster and scans. Numbering continues from the first category through Present. Student names and IDs reflect the current directory.</p>
  <?php else: ?>
    <div class="management-report-metrics"><div><span>Assessed absence fines</span><strong><?= $money($data['totals']['assessed']) ?></strong></div><div><span>Collected against these fines</span><strong><?= $money($data['totals']['collected']) ?></strong></div><div><span>Outstanding</span><strong><?= $money($data['totals']['outstanding']) ?></strong></div></div>
    <p class="management-report-note"><?= number_format($data['students']) ?> students · <?= number_format($data['events']) ?> events with assessed fines. Only finalized attendance with a positive recorded absence fine is included. Open or unstarted attendance does not create a fine.</p>
    <?php if(!empty($data['states']['OPEN'])): ?><p class="management-report-caution"><?= (int)$data['states']['OPEN'] ?> open attendance event(s) excluded from fine assessments.</p><?php endif; ?>
    <?php $grouped=[];foreach($data['rows']as$row)$grouped[$row['event_id']][]=$row;$number=0;foreach($grouped as$rows): ?>
      <section class="management-report-category"><h3><?= synk_management_h($rows[0]['title']) ?><span><?= synk_management_h($rows[0]['event_date']) ?></span></h3><div class="management-report-table-scroll"><table class="management-report-table"><thead><tr><th scope="col" class="report-number">No.</th><th scope="col">Student ID</th><th scope="col">Student name</th><th scope="col" class="amount">Assessed</th><th scope="col" class="amount">Collected</th><th scope="col" class="amount">Outstanding</th></tr></thead><tbody><?php foreach($rows as$row): ?><tr><td><?= ++$number ?></td><td><?= synk_management_h($row['student_number']) ?></td><td><?= synk_management_h($row['student_name']) ?></td><td class="amount"><?= $money($row['assessed']) ?></td><td class="amount"><?= $money($row['collected']) ?></td><td class="amount"><?= $money($row['outstanding']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
    <?php endforeach;if(!$grouped): ?><p class="report-empty">No finalized event absence fines for the selected period and event filter.</p><?php endif; ?>
